from r5lib import c as run
T1 = {"dm_status":"known","dm_type_recorded":"type_1","glucose_lowering_therapy":["insulin"]}
T2 = {"dm_status":"known","dm_type_recorded":"type_2"}
F = lambda **k: {"sex":"female", **k}
M = lambda **k: {"sex":"male", **k}
run(M(age_years=30, **T1, deep_rapid_breathing=True, acetone_breath=True), label="J01a T1 Kussmaul no glucose")
run(M(age_years=30, **T1, deep_rapid_breathing=True, acetone_breath=True), site="district", label="J01b district")
run(M(age_years=30, **T1, deep_rapid_breathing=True, capillary_glucose=7.0), label="J01c T1 Kussmaul glucose 7")
run(F(age_years=22, pregnant=False, bmi=19, polyuria=True, polydipsia=True, unexplained_weight_loss=True, hba1c=5.6, dm_status="not_known"), est=False, label="J02 symptoms + HbA1c 5.6")
run(M(age_years=25, **T1, capillary_glucose=22, vomiting=True, bohb=2.4), label="J03a T1 glu22 vomiting bohb2.4")
run(M(age_years=55, **T2, glucose_lowering_therapy=["metformin"], capillary_glucose=25, vomiting=True, urine_ketones="1plus"), label="J03b T2 glu25 vomit 1+")
run(M(age_years=55, **T2, glucose_lowering_therapy=["metformin","sglt2_inhibitor"], capillary_glucose=9.0, vomiting=True, abdominal_pain=True, urine_ketones="trace"), label="J03c SGLT2 vomit pain glu9 trace")
run(M(age_years=25, **T1, capillary_glucose=7.0, vomiting=True), label="J03d T1 vomit glu7")
run(M(age_years=25, **T1, capillary_glucose=22, vomiting=True, urine_ketones="neg"), site="district", label="J03e T1 glu22 vomit urine neg district")
run(F(age_years=50, capillary_glucose=16, capillary_glucose_context="random", polydipsia=True, egfr=20, bp_systolic=230, bp_diastolic=130, hypertensive_symptoms=True, dm_status="not_known"), est=False, label="J04 woman 50 preg blank")
run(F(age_years=50, capillary_glucose=16, capillary_glucose_context="random", polydipsia=True, egfr=20, bp_systolic=230, bp_diastolic=130, hypertensive_symptoms=True, dm_status="not_known"), est=False, site="district", label="J04 district")
run(M(age_years=12, **T1, capillary_glucose=14), band="child", label="J05 child T1 meter 14")
run(M(age_years=12, **T1, abdominal_pain=True, capillary_glucose=6.0, bohb=0.3), band="child", label="J06a child T1 pain glu6 bohb0.3")
run(M(age_years=12, **T1, abdominal_pain=True, capillary_glucose=6.0, urine_ketones="neg"), band="child", label="J06b urine neg")
run(M(age_years=12, **T1, abdominal_pain=True), band="child", label="J06c nothing measured")
run(M(age_years=40, dm_status="not_known", active_foot_ulcer=True), est=False, label="J07a non-DM ulcer")
run(M(age_years=40, dm_status="not_known", foot_hot_swollen=True), est=False, label="J07b non-DM hot foot")
run(F(age_years=8, active_foot_ulcer=True), est=False, band="child", label="J07c 8yo ulcer")
run(M(age_years=55, **T2, glucose_lowering_therapy=["metformin"], capillary_glucose=3.8, capillary_glucose_context="fasting"), label="J08 metformin 3.8")
run(M(age_years=55, **T2, glucose_lowering_therapy=["insulin"], capillary_glucose=2.4), label="J09a insulin 2.4")
run(M(age_years=10, **T1, capillary_glucose=2.5), band="child", label="J09b child T1 2.5")
run(M(age_years=25, **T1, capillary_glucose=25, deep_rapid_breathing=True, urine_ketones="3plus"), label="J09c DKA")
run(M(age_years=80, **T2, glucose_lowering_therapy=["gliclazide"], frailty_or_limited_life_expectancy=True, egfr=22, hba1c=6.4), band="older_adult", label="J11 80 frail gliclazide eGFR22 HbA1c6.4")
run(M(age_years=60, **T2, glucose_lowering_therapy=["metformin"], glycaemic_target_tier="relaxed", hba1c=7.6), label="J12a tier relaxed 7.6")
run(M(age_years=72, **T2, glucose_lowering_therapy=["metformin"], glycaemic_target_tier="general", hba1c=7.3), band="older_adult", label="J12b 72 general 7.3")
run(M(age_years=72, **T2, glucose_lowering_therapy=["metformin"], hba1c=7.3), band="older_adult", label="J12c 72 no tier 7.3")
run(M(age_years=55, **T2, retinopathy_stage="none", retina_view="not_attempted"), label="J13a")
run(M(age_years=55, **T2, retinopathy_stage="none"), label="J13b stage none only")
run(M(age_years=55, **T2, glucose_lowering_therapy=["metformin"], capillary_glucose=25, urine_ketones="neg"), label="J14a T2 25 neg")
run(M(age_years=45, dm_status="not_known", capillary_glucose=25, capillary_glucose_context="random", urine_ketones="neg"), est=False, site="district", label="J14b new 25 neg district")
run(F(age_years=32, pregnant=True, gestation_weeks=30, fasting_pg=5.5, bp_systolic=165, bp_diastolic=105), est=False, label="J15a 30w FPG5.5 165/105")
run(F(age_years=28, pregnant=True, gestation_weeks=26, **T1, bp_systolic=150, bp_diastolic=100), label="J15b preg T1 150/100")
run(M(age_years=45, dm_status="not_known", capillary_glucose=6.4, capillary_glucose_context="fasting"), est=False, site="district", label="J17 district fcap 6.4")
run(M(age_years=60, **T2, bp_systolic=230, bp_diastolic=130, hypertensive_symptoms=True), label="J18a 230/130 symptoms")
run(M(age_years=60, **T2, bp_systolic=182, bp_diastolic=112, hypertensive_symptoms=True), label="J18b 182/112 headache")
